#[test]
fn severity_numbers_text_and_parsing() {
    let nums: Vec<u8> = Severity::ALL.iter().map(|s| s.number()).collect();
    assert_eq!(nums, [1, 5, 9, 13, 17, 21]);
    let texts: Vec<String> = Severity::ALL.iter().map(|s| s.to_string()).collect();
    assert_eq!(texts, ["TRACE", "DEBUG", "INFO", "WARN", "ERROR", "FATAL"]);
    assert_eq!(Severity::default(), Severity::Info);
    for (n, s) in [
        (0, Severity::Info),
        (3, Severity::Trace),
        (7, Severity::Debug),
        (12, Severity::Info),
        (16, Severity::Warn),
        (20, Severity::Error),
        (24, Severity::Fatal),
    ] {
        assert_eq!(Severity::from_number(n), s, "{n}");
    }
    for (t, s) in [
        ("trace", Severity::Trace),
        ("DEBUG", Severity::Debug),
        ("information", Severity::Info),
        ("Warning", Severity::Warn),
        ("err", Severity::Error),
        ("critical", Severity::Fatal),
        (" 17 ", Severity::Error),
    ] {
        assert_eq!(t.parse::<Severity>().unwrap(), s, "{t}");
    }
    let err = "loud".parse::<Severity>().unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    assert!(Severity::Warn > Severity::Info);
}

#[test]
fn record_builders_and_json_roundtrip() {
    let ts = UNIX_EPOCH + Duration::from_nanos(1_700_000_000_123_456_789);
    let mut r = LogRecord::new(Severity::Error, "boom")
        .with_attribute("n", 1)
        .with_attribute("nested", json!({"a": [1, "x"]}))
        .with_trace("4bf92f3577b34da6a3ce929d0e0e4736", "00f067aa0ba902b7");
    r.timestamp = ts;
    r.trace_flags = Some(1);
    r.resource.insert("service.name".into(), "svc".into());
    let v = r.to_json_value();
    assert_eq!(v["timestamp"], "2023-11-14T22:13:20.123456789Z");
    assert_eq!(v["severity"], 17);
    assert_eq!(v["severityText"], "ERROR");
    assert_eq!(v["body"], "boom");
    assert_eq!(v["traceFlags"], 1);
    assert_eq!(v["resource"]["service.name"], "svc");
    assert!(v.get("observedTimestamp").is_none());
    r.observed_timestamp = Some(ts);
    let v = r.to_json_value();
    assert_eq!(v["observedTimestamp"], "2023-11-14T22:13:20.123456789Z");
    let back = LogRecord::from_json(&r.to_json()).unwrap();
    assert_eq!(back, r);
    assert!(r.json_size() > 50);
    assert!(r.contains_text("boo"));
    assert!(r.contains_text("x"));
    assert!(!r.contains_text("zzz"));
}

#[test]
fn json_form_parses_variants() {
    let parsed = LogRecord::from_json(
        r#"{"timestamp":"2026-01-02T05:04:05+02:00","severityText":"warning","severity":13,
            "body":{"k":1}}"#,
    )
    .unwrap();
    assert_eq!(parsed.severity, Severity::Warn);
    assert_eq!(parsed.severity_text, "warning");
    assert_eq!(parsed.body, r#"{"k":1}"#);
    assert!(parsed.attributes.is_empty());
    assert_eq!(
        parsed.timestamp,
        LogRecord::from_json(
            r#"{"timestamp":"2026-01-02T03:04:05Z","severityText":"","severity":0,"body":""}"#
        )
        .unwrap()
        .timestamp
    );
    let err =
        LogRecord::from_json(r#"{"timestamp":"never","severityText":"","severity":1,"body":""}"#)
            .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    assert!(LogRecord::from_json("[]").is_err());
}

#[test]
fn inputs_and_entries() {
    let ts = UNIX_EPOCH + Duration::from_secs(5);
    let i = LogInput::new("hello")
        .severity(Severity::Debug)
        .attribute("a", true)
        .timestamp(ts)
        .trace("t", "s");
    assert_eq!(i.severity, Some(Severity::Debug));
    assert_eq!(i.attributes["a"], AttrValue::Bool(true));
    assert_eq!(i.timestamp, Some(ts));
    assert_eq!(i.trace_id.as_deref(), Some("t"));
    assert_eq!(LogInput::from("x").message, "x");
    assert_eq!(LogInput::from(String::from("y")).message, "y");
    assert!(matches!(LogEntry::from("x"), LogEntry::Input(_)));
    assert!(matches!(
        LogEntry::from(String::from("x")),
        LogEntry::Input(_)
    ));
    assert!(matches!(LogEntry::from(i), LogEntry::Input(_)));
    assert!(matches!(
        LogEntry::from(LogRecord::new(Severity::Info, "r")),
        LogEntry::Record(_)
    ));
    let m: Attributes = attrs! { "a" => 1, "b" => "two" };
    assert_eq!(m.len(), 2);
    let empty: Attributes = attrs! {};
    assert!(empty.is_empty());
}

#[test]
fn redaction_keys_patterns_and_nesting() {
    assert!(DEFAULT_REDACT_KEYS.contains(&"api_key"));
    let p = RedactionProcessor::default();
    assert!(p.is_sensitive_key("X-Auth-TOKEN"));
    assert!(!p.is_sensitive_key("user"));
    let r = LogRecord::new(Severity::Info, "token=abc123 for user")
        .with_attribute("password", "hunter2")
        .with_attribute("user", "ada")
        .with_attribute(
            "nested",
            json!({"Api_Key": "k", "list": [{"secret": "s"}, "plain"], "ok": 1}),
        );
    let out = p.process(&r);
    assert_eq!(out.body, r.body, "no patterns by default");
    assert_eq!(out.attributes["password"], "[REDACTED]");
    assert_eq!(out.attributes["user"], "ada");
    assert_eq!(out.attributes["nested"]["Api_Key"], "[REDACTED]");
    assert_eq!(out.attributes["nested"]["list"][0]["secret"], "[REDACTED]");
    assert_eq!(out.attributes["nested"]["list"][1], "plain");
    assert_eq!(out.attributes["nested"]["ok"], 1);

    let custom = RedactionProcessor::new(["session"], vec![])
        .with_extra_keys(["pin"])
        .with_pattern(Regex::new(r"abc\d+").unwrap())
        .with_replacement("***");
    assert_eq!(custom.keys(), ["session", "pin"]);
    let out = custom.process(
        &r.clone()
            .with_attribute("PIN", 1234)
            .with_attribute("note", json!(["see abc999", {"x": "abc1"}])),
    );
    assert_eq!(out.body, "token=*** for user");
    assert_eq!(out.attributes["PIN"], "***");
    assert_eq!(
        out.attributes["password"], "hunter2",
        "custom keys replace the defaults"
    );
    assert_eq!(out.attributes["note"][0], "see ***");
    assert_eq!(out.attributes["note"][1]["x"], "***");
}
